const CONFIG = {
  // ===== Edita solo esto =====
  CORREO_JHINNA: 'PEGA_AQUI_EL_CORREO_DE_JHINNA',   // destinatario principal
  CORREO_COPIA: '',                                 // opcional: más correos separados por coma
  // ===========================
};
const b = $input.first().json.body || $input.first().json;
const s = b.semaforo || {};
const esc = x => String(x ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const fmt = iso => { try { return new Date(iso).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'long', timeStyle: 'short' }); } catch (e) { return iso; } };
const mapa = `https://www.google.com/maps?q=${s.lat},${s.lon}`;
const para = [CONFIG.CORREO_JHINNA, ...String(CONFIG.CORREO_COPIA || '').split(',')].map(x => x.trim()).filter(x => x && x.includes('@'));
const asunto = `🚦 Semáforo dañado #${s.id} · ${s.direccion} (Comuna ${s.comuna})`;
const fila = (k, v) => `<tr><td style="padding:6px 10px;color:#475569;font-weight:600;white-space:nowrap">${k}</td><td style="padding:6px 10px">${v}</td></tr>`;
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;color:#0f172a">
  <div style="background:#01334e;color:#fff;padding:14px 18px;border-radius:10px 10px 0 0"><b style="font-size:16px">ColAIre · Reporte de semáforo dañado</b><div style="font-size:12px;opacity:.8">Cali Resiliente · participación ciudadana</div></div>
  <table style="border-collapse:collapse;width:100%;border:1px solid #e2e8f0;font-size:14px">
    ${fila('Semáforo', '#' + esc(s.id))}
    ${fila('Dirección', esc(s.direccion))}
    ${fila('Comuna', esc(s.comuna))}
    ${fila('Tipo de daño', '<b style="color:#b91c1c">' + esc(b.tipo) + '</b>')}
    ${b.nota ? fila('Comentario', esc(b.nota)) : ''}
    ${fila('Ubicación', `${esc(s.lat)}, ${esc(s.lon)} · <a href="${mapa}">Ver en Google Maps</a>`)}
    ${fila('Hora del reporte', esc(b.hora_reporte_local || fmt(b.hora_reporte)) + (b.simulacion ? ' <span style="color:#7c3aed">(simulación 10 ago 2026)</span>' : ''))}
    ${fila('Enviado', esc(fmt(b.hora_envio || new Date().toISOString())))}
    ${fila('Reportado por', esc((b.reportado_por || {}).nombre) + ' · ' + esc((b.reportado_por || {}).rol))}
  </table>
  <p style="font-size:12px;color:#64748b">Notificación automática enviada también a la Secretaría de Movilidad en la plataforma ColAIre. Prototipo de demostración: no reemplaza la línea 123.</p></div>`;
return [{ json: { para: para.join(','), asunto, html, listo: para.length > 0, semaforo: s.id } }];

const prev = $('Preparar correo').first().json;
const g = $input.first().json;
const ok = prev.listo && !g.error && (g.id || g.threadId || g.labelIds);
return [{ json: { ok: true, correo: prev.listo ? (ok ? 'enviado' : 'error') : 'sin destinatario', para: prev.para, semaforo: prev.semaforo, detalle: g.error ? (g.error.message || String(g.error)) : null } }];
